CHECKSUM_PREFIX = "\n#MD5="
CHECK_INTERVAL = 24*3600
CLEANUP_INTERVAL = 90*24*3600
LOWEST_VERSION = Gem::Version.new('0')
CUTOFF_VERSION = Gem::Version.new('5.0.0')

@specific_version = nil
@target_id = nil
